using Microsoft.AspNetCore.Authentication.Cookies;using Microsoft.AspNetCore.Identity;using Microsoft.EntityFrameworkCore;using MyExpenseTracker.Api.Data;using MyExpenseTracker.Api.Models;
var b=WebApplication.CreateBuilder(args);b.Services.AddDbContext<AppDbContext>(o=>o.UseSqlServer(b.Configuration.GetConnectionString("DefaultConnection")));b.Services.AddScoped<IPasswordHasher<AppUser>,PasswordHasher<AppUser>>();b.Services.AddAuthentication(CookieAuthenticationDefaults.AuthenticationScheme).AddCookie(o=>{o.Cookie.Name="myexpense.auth";o.Cookie.HttpOnly=true;o.Cookie.SecurePolicy=CookieSecurePolicy.Always;o.Cookie.SameSite=SameSiteMode.Lax;o.ExpireTimeSpan=TimeSpan.FromHours(12);o.SlidingExpiration=true;o.Events.OnRedirectToLogin=c=>{c.Response.StatusCode=401;return Task.CompletedTask;};});b.Services.AddAuthorization();b.Services.AddControllers();var app=b.Build();app.UseHttpsRedirection();app.UseAuthentication();app.UseAuthorization();app.MapControllers();app.Run();